if (channel) {
  nsCOMPtr<nsIURI> uri;
  channel->GetURI(getter_AddRefs(uri));
  ssobj->innerScriptable->SetUri(uri);

  nsCOMPtr<nsIMailChannel> mailChannel = do_QueryInterface(channel);
  ssobj->innerScriptable->SetMailChannel(mailChannel);
}
